+func TestFliptAcceptServerVersionUnaryInterceptor(t *testing.T) {
+	tests := []struct {
+		name    string
+		header  string
+		version semver.Version
+	}{
+		{name: "missing", version: defaultFliptAcceptServerVersion},
+		{name: "invalid", header: "not-a-version", version: defaultFliptAcceptServerVersion},
+		{name: "prefixed", header: "v1.2.3", version: semver.Version{Major: 1, Minor: 2, Patch: 3}},
+		{name: "unprefixed", header: "1.2.3", version: semver.Version{Major: 1, Minor: 2, Patch: 3}},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			ctx := context.Background()
+			if tt.header != "" {
+				ctx = metadata.NewIncomingContext(ctx, metadata.Pairs(fliptAcceptServerVersionHeader, tt.header))
+			}
+
+			called := false
+			_, err := FliptAcceptServerVersionUnaryInterceptor(zaptest.NewLogger(t))(
+				ctx, nil, nil,
+				func(ctx context.Context, _ interface{}) (interface{}, error) {
+					called = true
+					assert.Equal(t, tt.version, FliptAcceptServerVersionFromContext(ctx))
+					return nil, nil
+				},
+			)
+			require.NoError(t, err)
+			assert.True(t, called)
+		})
+	}
+}
+
+func TestFliptAcceptServerVersionContext(t *testing.T) {
+	assert.Equal(t, defaultFliptAcceptServerVersion, FliptAcceptServerVersionFromContext(context.Background()))
+	version := semver.Version{Major: 2, Minor: 3, Patch: 4}
+	ctx := WithFliptAcceptServerVersion(context.Background(), version)
+	assert.Equal(t, version, FliptAcceptServerVersionFromContext(ctx))
+}
